CREATE TABLE IF NOT EXISTS `applicant` (`applicant_id` int AUTO_INCREMENT NOT NULL, `tracking_number` varchar(25) NOT NULL, `child_name` varchar(150) NOT NULL, `date_of_birth` date NOT NULL, `gender` enum('Male','Female') NOT NULL, `place_of_birth` varchar(150) NOT NULL, `birth_facility_code` varchar(50), `birth_notification_no` varchar(50) NOT NULL, `parent_national_id` varchar(12) NOT NULL, `parent_full_name` varchar(150) NOT NULL, `parent_relationship` enum('Mother','Father','Guardian') NOT NULL, `contact_phone` varchar(20) NOT NULL, `contact_email` varchar(100), `sub_county` varchar(100) NOT NULL, `ward` varchar(100) NOT NULL, `id_verification_status` varchar(30) NOT NULL DEFAULT 'UNVERIFIED', `iprs_reference_token` varchar(100), `iprs_verified_name` varchar(150), `verified_at` datetime, `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `applicant_id_pk` PRIMARY KEY(`applicant_id`), CONSTRAINT `applicant_tracking_unique` UNIQUE(`tracking_number`));
CREATE TABLE IF NOT EXISTS `application` (`application_id` int AUTO_INCREMENT NOT NULL, `tracking_number` varchar(25) NOT NULL, `applicant_id` int NOT NULL, `current_status` varchar(30) NOT NULL DEFAULT 'Submitted', `assigned_clerk_id` int, `assigned_registrar_id` int, `submitted_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, `last_updated` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `application_id_pk` PRIMARY KEY(`application_id`), CONSTRAINT `application_tracking_unique` UNIQUE(`tracking_number`));
CREATE TABLE IF NOT EXISTS `staff` (`staff_id` int AUTO_INCREMENT NOT NULL, `employee_id` varchar(20) NOT NULL, `full_name` varchar(150) NOT NULL, `email` varchar(100) NOT NULL, `phone_number` varchar(20) NOT NULL, `role` enum('Clerk','Registrar','Administrator','Auditor') NOT NULL, `sub_county` varchar(100) NOT NULL DEFAULT 'Nakuru Town East', `counter_number` varchar(10) NOT NULL DEFAULT '1', `is_active` boolean NOT NULL DEFAULT true, `eula_accepted_at` datetime, `last_login` datetime, `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `staff_id_pk` PRIMARY KEY(`staff_id`), CONSTRAINT `staff_employee_unique` UNIQUE(`employee_id`), CONSTRAINT `staff_email_unique` UNIQUE(`email`));
CREATE TABLE IF NOT EXISTS `status_history` (`history_id` int AUTO_INCREMENT NOT NULL, `application_id` int NOT NULL, `staff_id` int NOT NULL, `old_status` varchar(30) NOT NULL, `new_status` varchar(30) NOT NULL, `justification_notes` text NOT NULL, `changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `status_history_pk` PRIMARY KEY(`history_id`));
CREATE TABLE IF NOT EXISTS `verification_audit_log` (`audit_id` int AUTO_INCREMENT NOT NULL, `application_id` int, `staff_id` int, `action` varchar(80) NOT NULL, `parent_national_id_checked` varchar(12), `iprs_match_status` boolean, `hospital_record_match_status` boolean, `otp_verified` boolean, `face_match_confirmed` boolean, `verification_source` varchar(30), `discrepancy_reason` text, `client_ip_address` varchar(45) NOT NULL, `user_agent` text NOT NULL, `verification_timestamp` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `verification_audit_log_pk` PRIMARY KEY(`audit_id`));
CREATE TABLE IF NOT EXISTS `certificate` (`certificate_id` int AUTO_INCREMENT NOT NULL, `application_id` int NOT NULL, `certificate_number` varchar(50) NOT NULL, `security_serial_number` varchar(50) NOT NULL, `verification_qr_hash` varchar(255) NOT NULL, `issued_date` date NOT NULL, `printed_by_staff_id` int NOT NULL, `collected_date` date, `collector_national_id` varchar(12), `collector_name` varchar(150), `collector_signature_token` text, CONSTRAINT `certificate_pk` PRIMARY KEY(`certificate_id`), CONSTRAINT `certificate_application_unique` UNIQUE(`application_id`), CONSTRAINT `certificate_number_unique` UNIQUE(`certificate_number`), CONSTRAINT `certificate_serial_unique` UNIQUE(`security_serial_number`));
CREATE TABLE IF NOT EXISTS `sms_template` (`template_id` int AUTO_INCREMENT NOT NULL, `template_code` varchar(50) NOT NULL, `trigger_status` varchar(30) NOT NULL, `template_name` varchar(100) NOT NULL, `message_body` text NOT NULL, `is_active` boolean NOT NULL DEFAULT true, CONSTRAINT `sms_template_pk` PRIMARY KEY(`template_id`), CONSTRAINT `sms_template_code_unique` UNIQUE(`template_code`));
CREATE TABLE IF NOT EXISTS `sms_log` (`sms_id` int AUTO_INCREMENT NOT NULL, `application_id` int, `recipient_phone` varchar(20) NOT NULL, `message_text` text NOT NULL, `gateway_message_id` varchar(100), `delivery_status` varchar(20) NOT NULL DEFAULT 'Queued', `sent_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `sms_log_pk` PRIMARY KEY(`sms_id`));
CREATE TABLE IF NOT EXISTS `system_settings` (`setting_key` varchar(50) NOT NULL, `setting_value` text NOT NULL, `description` text, `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `system_settings_pk` PRIMARY KEY(`setting_key`));
CREATE INDEX `idx_applicant_parent_id` ON `applicant` (`parent_national_id`); CREATE INDEX `idx_applicant_notification_no` ON `applicant` (`birth_notification_no`); CREATE INDEX `idx_application_status` ON `application` (`current_status`); CREATE INDEX `idx_application_updated` ON `application` (`last_updated`); CREATE INDEX `idx_audit_time` ON `verification_audit_log` (`verification_timestamp`);
